import { Routes, Route, Navigate } from "react-router-dom";
import LoginHtmlPage from "../pages/LoginHtmlPage";
import OptionsPage from "../pages/OptionsPage";
import CampusComplaintPage from "../pages/CampusComplaintPage";
import ComplaintHistoryPage from "../pages/ComplaintHistoryPage";
import GatepassHtmlPage from "../pages/GatepassHtmlPage";
import MessTimingsPage from "../pages/MessTimingsPage";
import ProfileHtmlPage from "../pages/ProfileHtmlPage";
import HostelComplaintPage from "../pages/HostelComplaintPage";
import MessComplaintPage from "../pages/MessComplaintPage";
import Sq1ComplaintPage from "../pages/Sq1ComplaintPage";
import OtherComplaintPage from "../pages/OtherComplaintPage";
import BaristaMenuPage from "../pages/BaristaMenuPage";
import BaristaBillPage from "../pages/BaristaBillPage";

export default function AppRoutes() {
  return (
    <Routes>
      <Route path="/" element={<Navigate to="/login" replace />} />
      <Route path="/login" element={<LoginHtmlPage />} />

      {/* Converted from original HTML filenames */}
      <Route path="/options" element={<OptionsPage />} />
      <Route path="/campuscomplaint" element={<CampusComplaintPage />} />
      <Route path="/hostelcomplaint" element={<HostelComplaintPage />} />
      <Route path="/messcomplaint" element={<MessComplaintPage />} />
      <Route path="/sq1complaint" element={<Sq1ComplaintPage />} />
      <Route path="/other" element={<OtherComplaintPage />} />
      <Route path="/complaintHistory" element={<ComplaintHistoryPage />} />
      <Route path="/gatepass" element={<GatepassHtmlPage />} />
      <Route path="/mess2" element={<MessTimingsPage />} />
      <Route path="/profile" element={<ProfileHtmlPage />} />
      <Route path="/barista" element={<BaristaMenuPage />} />
      <Route path="/barista-bill" element={<BaristaBillPage />} />

      {/* TODO: convert and add remaining routes:
          check, backup2, other outlet menu pages + billing pages
      */}
    </Routes>
  );
}
